use cpm_service::{router,AppState};use std::{env,path::PathBuf};#[tokio::main]async fn main(){tracing_subscriber::fmt().with_env_filter(tracing_subscriber::EnvFilter::from_default_env()).init();let data=PathBuf::from(env::var("CPM_DATA_DIR").unwrap_or_else(|_|"./data".into()));let harness=PathBuf::from(env::var("CPM_UPSTREAM_HARNESS_ROOT").unwrap_or_else(|_|"./upstreams".into()));let state=AppState::open(data,&harness).expect("open application state");let address=env::var("CPM_BIND").unwrap_or_else(|_|"127.0.0.1:8080".into());let listener=tokio::net::TcpListener::bind(&address).await.expect("bind");axum::serve(listener,router(state)).await.expect("serve");}
